from fractions import Fraction
from math import gcd
import sys

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def expected_lis_length(N, A):
    total_sequences = 1
    for a in A:
        total_sequences *= a

    dp = [[Fraction(0) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0] = Fraction(1)

    for i in range(1, N + 1):
        for j in range(i + 1):
            dp[i][j] = dp[i-1][j] * Fraction(A[i-1] - j, A[i-1])
            if j > 0:
                dp[i][j] += dp[i-1][j-1] * Fraction(j, A[i-1])

    expected_value = sum(dp[N][j] * j for j in range(N + 1))

    expected_value *= total_sequences
    expected_value = int(expected_value)

    result = mod_inverse(total_sequences, 1000000007) * expected_value % 1000000007
    return result

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:]))
    print(expected_lis_length(N, A))

